1	//! Provider-specific hook configuration. Installation is not proof that a
2	//! harness has fired the hooks; doctor reports that boundary separately.
3	
4	use std::{
5	    fs::{self, OpenOptions},
6	    io::{self, Write},
7	    path::{Path, PathBuf},
8	    time::{SystemTime, UNIX_EPOCH},
9	};
10	
11	use serde_json::{Map, Value, json};
12	
13	use crate::{InstallError, config, install};
14	
15	pub(crate) const RTK_BACKUP: &str = ".claude/pixel-rtk-hooks.json";
16	/// Claude Code's team-shared project settings, usually committed.
17	pub(crate) const CLAUDE_SHARED_SETTINGS: &str = ".claude/settings.json";
18	/// Claude Code's personal per-project settings (gitignored by its convention):
19	/// the repo guard carries this machine's binary path, so it lives here.
20	pub(crate) const CLAUDE_LOCAL_SETTINGS: &str = ".claude/settings.local.json";
21	/// Devin CLI's personal per-project config; its `hooks` key is read like
22	/// `.devin/hooks.v1.json`, but it is not shared with the team.
23	pub(crate) const DEVIN_LOCAL_CONFIG: &str = ".devin/config.local.json";
24	/// Where an earlier `pixel install --repo` wrote the Devin guard. Devin CLI
25	/// never reads this file; install and uninstall take pixel's entry out of it.
26	pub(crate) const DEVIN_LEGACY_HOOKS: &str = ".devin/hooks.json";
27	/// Project-local snapshot of Codex `PreToolUse` groups adopted by the composed
28	/// guard.  It deliberately lives next to the project hook config so a runtime
29	/// never has to discover or execute the currently mutable hook configuration.
30	pub(crate) const CODEX_COMPOSED_BACKUP: &str = "pixel-composed-guard-backup.json";
31	const CODEX_COMPOSED_BACKUP_VERSION: u64 = 1;
32	
33	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
34	pub(crate) enum Provider {
35	    Claude,
36	    Codex,
37	    Devin,
38	}
39	
40	impl Provider {
41	    pub(crate) fn name(self) -> &'static str {
42	        match self {
43	            Self::Claude => "claude",
44	            Self::Codex => "codex",
45	            Self::Devin => "devin",
46	        }
47	    }
48	
49	    pub(crate) fn path(self, home: &Path) -> PathBuf {
50	        home.join(match self {
51	            Self::Claude => ".claude/settings.json",
52	            Self::Codex => config::CODEX_HOOKS_FILE,
53	            Self::Devin => ".config/devin/config.json",
54	        })
55	    }
56	
57	    pub(crate) fn shell(self) -> &'static str {
58	        if self == Self::Devin { "exec" } else { "Bash" }
59	    }
60	
61	    /// Claude Code's `Read` and `Grep` tools cannot be transparently rewired
62	    /// into a Bash call: the hook contract cannot change a tool type, so the
63	    /// Claude arm emits an advisory through `non_shell_advisory` instead.
64	    /// `Glob` is deliberately omitted — its docs in `guard.rs` explain that
65	    /// path enumeration alone is not a problem worth blocking; the actual
66	    /// `Read`/`Edit` of any result is itself guarded. Codex and Devin
67	    /// already widen the matcher for their own tool-name conventions.
68	    fn shell_matcher(self) -> &'static str {
69	        match self {
70	            Self::Codex => "Bash|shell|unified_exec|local_shell",
71	            // Devin's native read/search tools bypass exec rewrites and must
72	            // reach the guard so it can return its documented block response.
73	            Self::Devin => "exec|read|grep|glob|find_file_by_name",
74	            Self::Claude => "Bash|Read|Grep",
75	        }
76	    }
77	
78	    pub(crate) fn compact(self) -> &'static str {
79	        if self == Self::Devin {
80	            "PostCompaction"
81	        } else {
82	            "SessionStart"
83	        }
84	    }
85	}
86	
87	pub(crate) fn quoted_executable(exe: &Path) -> String {
88	    format!("'{}'", exe.to_string_lossy().replace('\'', "'\\''"))
89	}
90	
91	/// The path of an unquoted executable token, or of one single-quoted the way
92	/// [`quoted_executable`] writes it. An unquoted token holding whitespace is a
93	/// command line, not an executable, and has none.
94	fn unquoted_executable(executable: &str) -> Option<PathBuf> {
95	    if let Some(inner) = executable
96	        .strip_prefix('\'')
97	        .and_then(|s| s.strip_suffix('\''))
98	    {
99	        return Some(PathBuf::from(inner.replace("'\\''", "'")));
100	    }
101	    if executable.chars().any(char::is_whitespace) {
102	        return None;
103	    }
104	    Some(PathBuf::from(executable))
105	}
106	
107	/// The file name of an executable token (see [`unquoted_executable`]).
108	fn executable_name(executable: &str) -> Option<String> {
109	    unquoted_executable(executable)?
110	        .file_name()
111	        .map(|n| n.to_string_lossy().into_owned())
112	}
113	
114	/// What makes `command` one of pixel's hooks, or `None` for a foreign one:
115	/// the `run-hook` verb (`session-start`, `guard --provider claude`, ...) or,
116	/// for an install older than `run-hook`, the script's file name.
117	///
118	/// A `run-hook` command is pixel's when its executable carries one of the
119	/// names pixel installs itself under ([`config::PIXEL_EXECUTABLES`]: `pixel`
120	/// for a release, `pixel-dev` for `self-update --dev`) or the file name of

